import * as fs from 'fs';
import * as path from 'path';
import * as zlib from 'zlib';
import csv from 'csv-parser';
import Papa from 'papaparse';

interface ManifestRow {
  object_key: string;
  format: string;
  should_load: string;
  row_count: string;
}

interface OrderRecord {
  order_id: string;
  order_ts: string;
  customer_id: string;
  amount_cents: number;
  status: string;
  channel: string;
  country: string;
  promo_code?: string;
  source_object: string;
}

const S3_ENDPOINT = process.env.S3_ENDPOINT || 'file:///data/s3';
const S3_BUCKET = process.env.S3_BUCKET || 'foo-bar-prod-exports';
const S3_PREFIX = process.env.S3_PREFIX || 'initial-load/orders/2026-01/';
const S3_MANIFEST_PATH = process.env.S3_MANIFEST_PATH || '/data/s3/foo-bar-prod-exports/initial-load/orders/2026-01/manifest.csv';

async function parseManifest(): Promise<ManifestRow[]> {
  const manifestContent = fs.readFileSync(S3_MANIFEST_PATH, 'utf-8');
  const result = Papa.parse<ManifestRow>(manifestContent, {
    header: true,
    skipEmptyLines: true,
  });

  return result.data.filter(row => row.should_load === 'true');
}

async function readCSVFile(filePath: string, hasPromoCode: boolean = true): Promise<OrderRecord[]> {
  const records: OrderRecord[] = [];
  const stream = fs.createReadStream(filePath);

  return new Promise((resolve, reject) => {
    stream
      .pipe(csv())
      .on('data', (data: any) => {
        const record: OrderRecord = {
          order_id: data.order_id,
          order_ts: data.order_ts,
          customer_id: data.customer_id,
          amount_cents: parseInt(data.amount_cents, 10),
          status: data.status,
          channel: data.channel,
          country: data.country,
          promo_code: hasPromoCode ? (data.promo_code || null) : null,
          source_object: data.source_object,
        };
        records.push(record);
      })
      .on('end', () => resolve(records))
      .on('error', reject);
  });
}

async function readGZippedCSVFile(filePath: string): Promise<OrderRecord[]> {
  const records: OrderRecord[] = [];
  const stream = fs.createReadStream(filePath).pipe(zlib.createGunzip());

  return new Promise((resolve, reject) => {
    stream
      .pipe(csv())
      .on('data', (data: any) => {
        const record: OrderRecord = {
          order_id: data.order_id,
          order_ts: data.order_ts,
          customer_id: data.customer_id,
          amount_cents: parseInt(data.amount_cents, 10),
          status: data.status,
          channel: data.channel,
          country: data.country,
          promo_code: data.promo_code || null,
          source_object: data.source_object,
        };
        records.push(record);
      })
      .on('end', () => resolve(records))
      .on('error', reject);
  });
}

async function readJSONLFile(filePath: string): Promise<OrderRecord[]> {
  const content = fs.readFileSync(filePath, 'utf-8');
  const lines = content.trim().split('\n');
  const records: OrderRecord[] = [];

  for (const line of lines) {
    if (line.trim()) {
      const data = JSON.parse(line);
      const record: OrderRecord = {
        order_id: data.order_id,
        order_ts: data.order_ts,
        customer_id: data.customer_id,
        amount_cents: data.amount_cents,
        status: data.status,
        channel: data.channel,
        country: data.country,
        promo_code: data.promo_code,
        source_object: data.source_object,
      };
      records.push(record);
    }
  }

  return records;
}

async function readParquetFile(filePath: string): Promise<OrderRecord[]> {
  // For now, let's skip Parquet files and implement them later if needed
  // We can use ClickHouse's native Parquet support instead
  console.log(`Skipping Parquet file for now: ${filePath}`);
  return [];
}

async function insertRecordsToClickHouse(records: OrderRecord[]): Promise<void> {
  if (records.length === 0) return;

  // Prepare the INSERT statement
  const values = records.map(record => {
    const formattedPromoCode = record.promo_code ? `'${record.promo_code.replace(/'/g, "''")}'` : 'NULL';
    return `('${record.order_id}', '${record.order_ts}', '${record.customer_id}', ${record.amount_cents}, '${record.status}', '${record.channel}', '${record.country}', ${formattedPromoCode}, '${record.source_object}')`;
  }).join(',\n');

  const insertSQL = `
    INSERT INTO InitialLoadOrders
    (order_id, order_ts, customer_id, amount_cents, status, channel, country, promo_code, source_object)
    VALUES
    ${values}
  `;

  // Write to a file that we can execute via moose query
  fs.writeFileSync('/tmp/batch_insert.sql', insertSQL);

  console.log(`Inserting ${records.length} records...`);

  // Execute via moose query
  const { execSync } = require('child_process');
  try {
    execSync('moose query "$(cat /tmp/batch_insert.sql)" > /dev/null 2>&1');
    console.log(`✅ Successfully inserted ${records.length} records`);
  } catch (error) {
    console.error(`❌ Error inserting records:`, error);
    throw error;
  }
}

async function processFile(manifestRow: ManifestRow): Promise<OrderRecord[]> {
  const basePath = '/data/s3/foo-bar-prod-exports';
  const filePath = path.join(basePath, manifestRow.object_key);

  console.log(`Processing ${manifestRow.format} file: ${filePath}`);

  // Skip files under archive/replayed
  if (manifestRow.object_key.includes('archive/replayed')) {
    console.log(`Skipping archived file: ${filePath}`);
    return [];
  }

  let records: OrderRecord[] = [];

  switch (manifestRow.format) {
    case 'csv':
      // Check if this is the file missing promo_code column
      const hasPromoCode = !manifestRow.object_key.includes('dt=2026-01-04/hour=16');
      records = await readCSVFile(filePath, hasPromoCode);
      break;
    case 'csv.gz':
      records = await readGZippedCSVFile(filePath);
      break;
    case 'jsonl':
      records = await readJSONLFile(filePath);
      break;
    case 'parquet':
      records = await readParquetFile(filePath);
      break;
    default:
      console.error(`Unknown format: ${manifestRow.format}`);
      return [];
  }

  return records;
}

async function main() {
  try {
    console.log('🚀 Starting initial load process...');

    // Parse manifest
    console.log('📋 Parsing manifest...');
    const manifestRows = await parseManifest();
    console.log(`Found ${manifestRows.length} files to load`);

    // Process each file
    let totalRecords = 0;
    const batchSize = 5000; // Process in batches to avoid memory issues
    let allRecords: OrderRecord[] = [];

    for (const manifestRow of manifestRows) {
      const records = await processFile(manifestRow);
      allRecords.push(...records);

      // Insert in batches to avoid overwhelming ClickHouse
      if (allRecords.length >= batchSize) {
        await insertRecordsToClickHouse(allRecords);
        totalRecords += allRecords.length;
        allRecords = [];
      }
    }

    // Insert remaining records
    if (allRecords.length > 0) {
      await insertRecordsToClickHouse(allRecords);
      totalRecords += allRecords.length;
    }

    console.log(`✅ Initial load completed! Total records processed: ${totalRecords}`);

    // Run validation queries
    console.log('🔍 Running validation queries...');
    await runValidation();

  } catch (error) {
    console.error('❌ Error during initial load:', error);
    process.exit(1);
  }
}

async function runValidation(): Promise<void> {
  const { execSync } = require('child_process');

  try {
    console.log('Checking total unique orders...');
    const uniqueOrdersResult = execSync('moose query "SELECT COUNT(DISTINCT order_id) as unique_orders FROM InitialLoadOrders" 2>/dev/null').toString();
    console.log('Unique orders result:', uniqueOrdersResult);

    console.log('Checking sum of amount_cents...');
    const sumResult = execSync('moose query "SELECT SUM(amount_cents) as total_amount FROM InitialLoadOrders" 2>/dev/null').toString();
    console.log('Sum result:', sumResult);

    console.log('Checking status counts...');
    const statusResult = execSync('moose query "SELECT status, COUNT(*) as count FROM InitialLoadOrders GROUP BY status ORDER BY status" 2>/dev/null').toString();
    console.log('Status counts:', statusResult);

    console.log('Checking distinct source_object values...');
    const sourceResult = execSync('moose query "SELECT COUNT(DISTINCT source_object) as distinct_sources FROM InitialLoadOrders" 2>/dev/null').toString();
    console.log('Distinct sources:', sourceResult);

    console.log('Checking for duplicate order_ids...');
    const duplicateResult = execSync('moose query "SELECT COUNT(*) as duplicates FROM (SELECT order_id, COUNT(*) as cnt FROM InitialLoadOrders GROUP BY order_id HAVING cnt > 1)" 2>/dev/null').toString();
    console.log('Duplicates:', duplicateResult);

    console.log('Checking for archive/replayed source_objects...');
    const archivedResult = execSync('moose query "SELECT COUNT(*) as archived_count FROM InitialLoadOrders WHERE source_object LIKE \'%archive/replayed%\'" 2>/dev/null').toString();
    console.log('Archived rows:', archivedResult);

  } catch (error) {
    console.error('Error running validation:', error);
  }
}

if (require.main === module) {
  main();
}

