import * as fs from 'fs';
import * as path from 'path';
import Papa from 'papaparse';
import { execSync } from 'child_process';

interface ManifestRow {
  object_key: string;
  format: string;
  should_load: string;
  row_count: string;
}

const S3_MANIFEST_PATH = process.env.S3_MANIFEST_PATH || '/data/s3/foo-bar-prod-exports/initial-load/orders/2026-01/manifest.csv';
const USER_FILES_DIR = '/workspace/orders-analytics/.moose/native_infra/clickhouse/data/user_files';

async function parseManifest(): Promise<ManifestRow[]> {
  const manifestContent = fs.readFileSync(S3_MANIFEST_PATH, 'utf-8');
  const result = Papa.parse<ManifestRow>(manifestContent, {
    header: true,
    skipEmptyLines: true,
  });

  return result.data.filter(row => row.should_load === 'true');
}

async function getLoadedSources(): Promise<Set<string>> {
  try {
    const result = execSync(
      'cd /workspace/orders-analytics && moose query "SELECT DISTINCT source_object FROM InitialLoadOrders"',
      { encoding: 'utf8', stdio: 'pipe' }
    );

    const loadedSources = new Set<string>();

    // Parse the JSON lines output from moose query
    const lines = result.trim().split('\n');
    for (const line of lines) {
      if (line.startsWith('{') && line.includes('source_object')) {
        try {
          const parsed = JSON.parse(line);
          if (parsed.source_object) {
            loadedSources.add(parsed.source_object);
          }
        } catch (e) {
          // Skip invalid JSON lines
        }
      }
    }

    return loadedSources;
  } catch (error) {
    // If query fails (e.g., table is empty), return empty set
    return new Set<string>();
  }
}

async function copyFileToUserFiles(sourcePath: string, targetName: string): Promise<string> {
  const targetPath = path.join(USER_FILES_DIR, targetName);
  fs.copyFileSync(sourcePath, targetPath);
  return targetName;
}

