        source_object
      FROM file('${filename}', 'CSV',
        'order_id String, order_ts String, customer_id String, amount_cents UInt32, status String, channel String, country String, promo_code String, source_object String')
    `;
  } else {
    sql = `
      INSERT INTO InitialLoadOrders
      SELECT
        order_id,
        parseDateTimeBestEffort(order_ts) as order_ts,
        customer_id,
        amount_cents,
        status,
        channel,
        country,
        NULL as promo_code,
        source_object
      FROM file('${filename}', 'CSV',
        'order_id String, order_ts String, customer_id String, amount_cents UInt32, status String, channel String, country String, source_object String')
    `;
  }

  console.log(`Loading CSV: ${sourceObject}`);
  execSync(`cd /workspace/orders-analytics && moose query "${sql}"`, { stdio: 'pipe' });
}

