        break;
      case 'jsonl':
        await loadJSONLFile(targetName, manifestRow.object_key);
        break;
      case 'parquet':
        await loadParquetFile(targetName, manifestRow.object_key);
        break;
      default:
        console.error(`Unknown format: ${manifestRow.format}`);
        return;
    }

    console.log(`✅ Successfully loaded ${manifestRow.object_key}`);

  } catch (error) {
    console.error(`❌ Error loading ${manifestRow.object_key}:`, error);
    throw error;
  } finally {
    // Clean up the copied file
    try {
      fs.unlinkSync(path.join(USER_FILES_DIR, targetName));
    } catch (e) {
      // File might not exist, ignore cleanup errors
    }
  }
}

